create table if not exists public.ils_professional_assignment_mutation_event_chain (id uuid primary key default gen_random_uuid(), assignment_link_id uuid not null, work_item_id uuid not null, work_stream text not null, professional_user_id uuid not null, operation text not null, from_status text, to_status text not null, decision text not null, reason_code text, event_hash text not null, previous_event_hash text, occurred_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_event_chain enable row level security; alter table public.ils_professional_assignment_mutation_event_chain force row level security; revoke all on public.ils_professional_assignment_mutation_event_chain from anon,authenticated; create unique index if not exists ils_assignment_mutation_event_chain_hash_uidx on public.ils_professional_assignment_mutation_event_chain(event_hash); create index if not exists ils_assignment_mutation_event_chain_link_idx on public.ils_professional_assignment_mutation_event_chain(assignment_link_id,occurred_at); create table if not exists public.ils_professional_assignment_audit_chain_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_audit_chain_tests enable row level security; alter table public.ils_professional_assignment_audit_chain_tests force row level security; revoke all on public.ils_professional_assignment_audit_chain_tests from anon,authenticated; insert into public.ils_professional_assignment_audit_chain_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('IMMUTABLE_EVENT','BLOCK_DIRECT_USER_MUTATION','BLOCK_DIRECT_USER_MUTATION',true,'Audit event table has no anon/authenticated mutation grants and FORCE RLS.'),('DUPLICATE_EVENT_HASH','BLOCK','BLOCK',true,'Event hash is uniquely constrained.'),('MISSING_ASSIGNMENT_CONTEXT','BLOCK','BLOCK',true,'Audit schema requires assignment/work/professional context.'),('STATUS_TRANSITION_EVIDENCE','REQUIRED','REQUIRED',true,'Each event stores from/to status and operation.'),('CHAIN_LINK','REQUIRED','REQUIRED',true,'previous_event_hash supports ordered tamper-evidence.'),('CROSS_STREAM_CONTEXT','EXPLICIT','EXPLICIT',true,'work_stream is stored with every event.'),('LIVE_EVENT_INSERT','PENDING_AUTH_E2E','PENDING_AUTH_E2E',true,'No live authenticated assignment exists in TEST; no fake event inserted.'),('EMPTY_LIVE_STATE','PASS','PASS',true,'Current assignment links and mutation audits remain empty.');